63: pub async fn enter_safe_mode(
64:     shared_state: &Arc<Mutex<SharedState>>,
65:     chrome_state: &Arc<RwLock<ChromeState>>,
66: ) -> SafeModeEntryResult {
67:     let now_ms = now_wall_ms();
68:     let now_us = now_ms.saturating_mul(1_000);
69: 
70:     let (leases_suspended, sessions_notified) = {
71:         let st = shared_state.lock().await;
72: 
73:         // Guard: idempotent. `safe_mode_atomic` is the single source of truth.
74:         if st.safe_mode_atomic.load(Ordering::Acquire) {
75:             return SafeModeEntryResult {
76:                 leases_suspended: 0,
77:                 sessions_notified: 0,
78:             };
79:         }
80: 
81:         // Suspend all ACTIVE leases (NOT revoke).
82:         let leases_suspended = {
83:             let mut scene = st.scene.lock().await;
84:             scene.suspend_all_leases(now_ms);
85:             scene
86:                 .leases
87:                 .values()
88:                 .filter(|l| l.state == LeaseState::Suspended)
89:                 .count()
90:         };
91: 
92:         // The event thread reads this lock-free and mutation intake reads it
93:         // under the SharedState lock; Release pairs with their Acquire loads.
94:         st.safe_mode_atomic.store(true, Ordering::Release);
95: 
96:         // sequence = 0: the session handler stamps the per-session sequence
97:         // before delivery; a shared broadcast cannot.
98:         let suspended_msg = ServerMessage {
99:             sequence: 0,
100:             timestamp_wall_us: now_us,
101:             payload: Some(ServerPayload::SessionSuspended(SessionSuspended {
102:                 reason: "safe_mode_entered".to_string(),
103:                 timestamp_wall_us: now_us,
104:             })),
105:         };

128: pub async fn exit_safe_mode(
129:     shared_state: &Arc<Mutex<SharedState>>,
130:     chrome_state: &Arc<RwLock<ChromeState>>,
131: ) -> SafeModeExitResult {
132:     let now_ms = now_wall_ms();
133:     let now_us = now_ms.saturating_mul(1_000);
134: 
135:     let st = shared_state.lock().await;
136:     if !st.safe_mode_atomic.load(Ordering::Acquire) {
137:         return SafeModeExitResult {
138:             exited: false,
139:             leases_resumed: 0,
140:             sessions_notified: 0,
141:         };
142:     }
143: 
144:     // Dismiss the overlay first so the next frame has none.
145:     chrome_state
146:         .write()
147:         .unwrap_or_else(|poisoned| poisoned.into_inner())
148:         .safe_mode_active = false;
149: 
150:     let leases_resumed = {
151:         let mut scene = st.scene.lock().await;
152:         let suspended = scene
153:             .leases
154:             .values()
155:             .filter(|l| l.state == LeaseState::Suspended)
156:             .count();
157:         scene.resume_all_leases(now_ms);
158:         suspended
159:     };
160: 
161:     // Mutation intake accepts new batches again.
162:     st.safe_mode_atomic.store(false, Ordering::Release);
163: 
164:     let resumed_msg = ServerMessage {
165:         sequence: 0,
166:         timestamp_wall_us: now_us,
167:         payload: Some(ServerPayload::SessionResumed(SessionResumed {
168:             timestamp_wall_us: now_us,
169:         })),
170:     };
171:     let sessions_notified = st.sessions.broadcast_server_message(resumed_msg);
172: 
173:     SafeModeExitResult {
174:         exited: true,
175:         leases_resumed,
176:         sessions_notified,
177:     }
178: }
