180: /// Current wall-clock time in milliseconds since Unix epoch.
181: fn now_wall_ms() -> u64 {
182:     SystemTime::now()
183:         .duration_since(UNIX_EPOCH)
184:         .unwrap_or_default()
185:         .as_millis() as u64
186: }
