1396:         }
1397:         // Restore TTL: set granted_at_ms so that granted_at_ms + ttl_ms
1398:         // equals now_ms + remaining.
1399:         if let Some(remaining) = self.ttl_remaining_at_suspend_ms {
1400:             self.granted_at_ms = now_ms;
1401:             self.ttl_ms = remaining;
1402:         }
1403:         self.suspended_at_ms = None;
1404:         self.ttl_remaining_at_suspend_ms = None;
