1770:     pub fn process_drag_handle_pointer(
1771:         &mut self,
1772:         event: &PointerEvent,
1773:         hit_interaction_id: &str,
1774:         element_id: SceneId,
1775:         element_kind: DragHandleElementKind,
1776:         element_bounds: tze_hud_scene::Rect,
1777:         display_width: f32,
1778:         display_height: f32,
1779:         is_header_band: bool,
1780:     ) -> DragEventOutcome {
1781:         let device_id = event.device_id;
1782: 
1783:         // Select threshold: primary pointer = 250ms, touch = 1000ms.
1784:         let threshold_ms = if device_id == 0 {
1785:             drag::LONG_PRESS_POINTER_THRESHOLD_MS
1786:         } else {
1787:             drag::LONG_PRESS_TOUCH_THRESHOLD_MS
1788:         };
1789: 
1790:         match event.kind {
1791:             PointerEventKind::Down => {
1792:                 // Start accumulating for this device.
1793:                 let state = DeviceDragState::new(
1794:                     hit_interaction_id.to_string(),
1795:                     element_id,
1796:                     element_kind,
1797:                     event.x,
1798:                     event.y,
1799:                     threshold_ms,
1800:                     is_header_band,
1801:                 );
1802:                 self.drag_states.insert(device_id, state);
1803:                 DragEventOutcome::Accumulating { progress: 0.0 }
1804:             }
1805:             PointerEventKind::Move => {
1806:                 let Some(state) = self.drag_states.get_mut(&device_id) else {
1807:                     return DragEventOutcome::Idle;
1808:                 };
1809:                 match state.phase {
1810:                     DragPhase::Idle => DragEventOutcome::Idle,
1811:                     DragPhase::Accumulating => {
1812:                         // Immediate (portal header-band / titlebar) handles engage
1813:                         // on the FIRST move — no long-press hold, no early-movement
1814:                         // cancel (hud-cpjqe). This is what makes a fast titlebar
1815:                         // drag reliable; the grip path below keeps the hysteresis.
1816:                         if state.immediate {
1817:                             state.phase = DragPhase::Activated;
1818:                             state.grab_offset_x = event.x - element_bounds.x;
1819:                             state.grab_offset_y = event.y - element_bounds.y;
1820:                             return DragEventOutcome::Activated {
1821:                                 element_id: state.element_id,
1822:                                 element_kind: state.element_kind,
1823:                             };
1824:                         }
1825:                         // Check movement cancellation.
1826:                         if state.has_exceeded_movement_tolerance(event.x, event.y) {
1827:                             let _ = self.drag_states.remove(&device_id);
1828:                             return DragEventOutcome::Cancelled;
1829:                         }
1830:                         // Check threshold.
1831:                         if state.is_threshold_met() {
1832:                             // Activate drag: record grab offset.
1833:                             state.phase = DragPhase::Activated;
1834:                             state.grab_offset_x = event.x - element_bounds.x;
1835:                             state.grab_offset_y = event.y - element_bounds.y;
1836:                             return DragEventOutcome::Activated {
1837:                                 element_id: state.element_id,
1838:                                 element_kind: state.element_kind,
1839:                             };
1840:                         }
1841:                         // Accumulating — update progress.
1842:                         let progress = state.progress();
1843:                         state.last_progress = progress;
1844:                         DragEventOutcome::Accumulating { progress }
1845:                     }

