341:     pub fn system(binds: Arc<Mutex<Vec<SocketAddr>>>, extra_ports: Vec<u16>) -> Self {
342:         Self::new(move || {
343:             let tailnet: Vec<SocketAddr> = binds
344:                 .lock()
