346:                 .iter()
347:                 .copied()
348:                 .filter(|a| !crate::net_addrs::tailnet_addrs(&[a.ip()]).is_empty())
349:                 .collect();
350:             if !cfg!(target_os = "windows") || tailnet.is_empty() {
351:                 return TailnetInbound::NotApplicable;
