171:     /// Create a fade-in state (opacity 0 → 1) with the given duration.
172:     pub(crate) fn fade_in(duration_ms: u32) -> Self {
173:         Self {
174:             transition_start: std::time::Instant::now(),
175:             duration_ms,
176:             from_opacity: 0.0,
177:             target_opacity: 1.0,
178:         }
179:     }
