181:     /// Create a fade-in state starting from `from_opacity` rather than 0.
182:     ///
183:     /// Used for **transition interrupt semantics**: when a new publish arrives
184:     /// during an active fade-out, the fade-out is cancelled and a fade-in begins
185:     /// from the current composite opacity (not from zero).  This prevents blank
186:     /// frames during rapid replacement.
187:     ///
188:     /// Per spec §Subtitle Contention Policy — Latest Wins, Transition interrupt
189:     /// semantics note: "the fade-out MUST be cancelled immediately and the new
190:     /// content MUST begin its transition_in_ms fade-in from the current composite
191:     /// opacity (not from zero)."
192:     pub(crate) fn fade_in_from(duration_ms: u32, from_opacity: f32) -> Self {
193:         Self {
194:             transition_start: std::time::Instant::now(),
195:             duration_ms,
196:             from_opacity: from_opacity.clamp(0.0, 1.0),
197:             target_opacity: 1.0,
198:         }
199:     }
200: 
201:     /// Create a fade-out state (opacity 1 → 0) with the given duration.
202:     pub(crate) fn fade_out(duration_ms: u32) -> Self {
203:         Self {
204:             transition_start: std::time::Instant::now(),
205:             duration_ms,
206:             from_opacity: 1.0,
207:             target_opacity: 0.0,
208:         }
209:     }
