211:     /// Raw linear progress `∈ [0, 1]` derived from elapsed wall time.
212:     ///
213:     /// A `duration_ms` of `0` reports `1.0` (already complete). Split out so the
214:     /// time source and the interpolation math are independently testable.
215:     #[inline]
216:     pub(crate) fn linear_progress(&self) -> f32 {
217:         if self.duration_ms == 0 {
218:             return 1.0;
219:         }
220:         let elapsed_ms = self.transition_start.elapsed().as_millis() as f32;
221:         (elapsed_ms / self.duration_ms as f32).clamp(0.0, 1.0)
222:     }
