307: impl PublicationAnimationState {
308:     /// Create a new state for a freshly-seen publication.
309:     pub(crate) fn new(ttl_ms: Option<u64>, source_expiry_us: Option<u64>) -> Self {
310:         Self {
311:             first_seen: std::time::Instant::now(),
312:             ttl_ms,
313:             source_expiry_us,
314:             fade_start: None,
315:             fade_duration_ms: NOTIFICATION_FADE_OUT_MS,
316:         }
317:     }
318: 
319:     /// Check whether the TTL has expired and start the fade if so.
320:     ///
321:     /// Must be called once per frame per publication.  Idempotent after the
322:     /// fade has started.
323:     pub(crate) fn tick(&mut self) {
324:         if self.fade_start.is_none()
325:             && self
326:                 .ttl_ms
327:                 .is_some_and(|ttl| self.first_seen.elapsed().as_millis() as u64 >= ttl)
328:         {
329:             self.fade_start = Some(std::time::Instant::now());
330:         }
331:     }
332: 
333:     /// Follow a changed record expiry (`hud_hold`): the fade delay counts from
334:     /// now, and a fade already under way is cancelled.
335:     pub(crate) fn retarget(&mut self, ttl_ms: Option<u64>, source_expiry_us: Option<u64>) {
336:         *self = Self::new(ttl_ms, source_expiry_us);
337:     }
338: 
339:     /// Returns the current effective opacity for this publication (0.0–1.0).
340:     ///
341:     /// Before fade: 1.0.
342:     /// During fade: linear interpolation from 1.0 → 0.0.
343:     /// After fade: 0.0.
344:     pub(crate) fn current_opacity(&self) -> f32 {
345:         let Some(start) = self.fade_start else {
346:             return 1.0;
347:         };
348:         if self.fade_duration_ms == 0 {
349:             return 0.0;
350:         }
351:         let elapsed_ms = start.elapsed().as_millis() as f32;
352:         let t = (elapsed_ms / self.fade_duration_ms as f32).clamp(0.0, 1.0);
353:         1.0 - t
354:     }
355: 
356:     /// Instant at which the fade-out will start, or `None` once it has (or
357:     /// when held: a held publication schedules no wake).
358:     pub(crate) fn fade_start_deadline(&self) -> Option<std::time::Instant> {
359:         if self.fade_start.is_some() {
360:             return None;
361:         }
362:         self.ttl_ms
363:             .map(|ttl| self.first_seen + std::time::Duration::from_millis(ttl))
364:     }
365: 
366:     /// Returns `true` while the fade-out is running (started, not complete).
367:     pub(crate) fn is_fading(&self) -> bool {
368:         self.fade_start.is_some() && !self.is_fade_complete()
369:     }
370: 
371:     /// Returns `true` when the fade-out transition has fully completed.
372:     pub(crate) fn is_fade_complete(&self) -> bool {
373:         let Some(start) = self.fade_start else {
374:             return false;
375:         };
376:         start.elapsed().as_millis() >= self.fade_duration_ms as u128
377:     }

465:     ///
466:     /// Call order per frame: `update_zone_animations` → `update_publication_animations`
467:     /// → `prune_faded_publications(scene)` → render.
468:     pub fn update_publication_animations(&mut self, scene: &SceneGraph) {
469:         let now_us = scene.now_wall_us();
470:         for (zone_name, publishes) in &scene.zone_registry.active_publishes {
471:             let zone_def = match scene.zone_registry.zones.get(zone_name) {
472:                 Some(z) => z,
473:                 None => continue,
474:             };
475:             // Only Stack zones get per-publication TTL fade-out.
476:             if !matches!(zone_def.contention_policy, ContentionPolicy::Stack { .. }) {
477:                 continue;
478:             }
479: 
480:             let zone_states = self
481:                 .pub_animation_states
482:                 .entry(zone_name.clone())
483:                 .or_default();
484: 
485:             // Build the set of currently-active pub keys for this zone.
486:             let active_keys: std::collections::HashSet<PubKey> = publishes
487:                 .iter()
488:                 .map(|r| (r.published_at_wall_us, r.publisher_namespace.clone()))
489:                 .collect();
490: 
491:             // Prune stale entries (publications removed from active_publishes).
492:             zone_states.retain(|k, _| active_keys.contains(k));
493: 
494:             // Ensure every active publication has an animation state; tick existing ones.
495:             for record in publishes {
496:                 let ttl_ms = Self::publication_fade_delay_ms(record, now_us);
497:                 let key: PubKey = (
498:                     record.published_at_wall_us,
499:                     record.publisher_namespace.clone(),
500:                 );
501:                 let state = zone_states.entry(key).or_insert_with(|| {
502:                     PublicationAnimationState::new(ttl_ms, record.expires_at_wall_us)
503:                 });
504:                 if state.source_expiry_us != record.expires_at_wall_us {
505:                     state.retarget(ttl_ms, record.expires_at_wall_us);
506:                 }
507:                 state.tick();
508:             }
509:         }
510: 
511:         // Prune zones no longer present in active_publishes.
512:         self.pub_animation_states
513:             .retain(|zone_name, _| scene.zone_registry.active_publishes.contains_key(zone_name));
514:     }
515: 
516:     /// Delay (ms from `now_us`) until the fade-out of one publication begins,
517:     /// or `None` when it has no expiry and is held until cleared.
518:     ///
519:     /// The fade starts `NOTIFICATION_FADE_OUT_MS` before the expiry so it
520:     /// completes before `drain_expired_zone_publications` removes the record
